with this new implementation (keep it directly after the constants / in the same location):

```
function getExistingToolErrorText(part: UIMessagePart): string | undefined {
	if ('errorText' in part && typeof part.errorText === 'string' && part.errorText.trim()) {
		return part.errorText;
	}
	return undefined;
}

/**
 * Settles any tool part left in a non-terminal state.
 *
 * A pending tool part is only labeled as a user interruption when the run was
 * genuinely stopped by the user (`userAborted`). Otherwise it is settled with a
 * neutral message so a lost/torn-down result is never falsely blamed on the
 * user. An error already captured on the part is always preserved.
 */
export function settleInterruptedToolParts(
	messages: UIMessage[],
	options: { userAborted?: boolean } = {},
): UIMessage[] {
	const fallbackErrorText = options.userAborted ? INTERRUPTED_TOOL_ERROR_TEXT : INCOMPLETE_TOOL_ERROR_TEXT;
	return messages.map((message) => {
		if (message.role !== 'assistant') {
			return message;
		}
		let changed = false;
		const newParts = message.parts.map((part) => {
			if (!isToolUIPart(part) || SETTLED_TOOL_STATES.has(part.state)) {
				return part;
			}
			changed = true;
			return {
				...part,
				state: 'output-error',
				input: part.input ?? {},
				errorText: getExistingToolErrorText(part) ?? fallbackErrorText,
			} as UIMessagePart;
		});
		return changed ? { ...message, parts: newParts } : message;
	});
}
```

