/**
 * Normalizes filesystem errors into clear, deterministic messages so tool
 * results surface the real cause (e.g. a missing path) instead of a raw or
 * generic failure.
 */
export const toToolFsError = (error: unknown, virtualPath: string): Error => {
	const code = (error as NodeJS.ErrnoException | null)?.code;
	switch (code) {
		case 'ENOENT':
			return new Error(`Path '${virtualPath}' does not exist (ENOENT)`);
		case 'ENOTDIR':
			return new Error(`Path '${virtualPath}' is not a directory (ENOTDIR)`);
		case 'EISDIR':
			return new Error(`Path '${virtualPath}' is a directory, not a file (EISDIR)`);
		case 'EACCES':
			return new Error(`Access denied to path '${virtualPath}' (EACCES)`);
		default:
			return error instanceof Error ? error : new Error(String(error));
	}
};
```

